update(dt60) {
  this.vy += GRAVITY * timeScale * overclockMult * dt60;
  this.vx *= Math.pow(FRICTION, dt60); // exponential friction over time
  this.x += this.vx * timeScale * dt60;
  this.y += this.vy * timeScale * dt60;
  this.stuckFrames += dt60; // time-based, not frame-based
  if (this.teleportCooldown > 0) this.teleportCooldown -= dt60;
  /* mini-balls also scaled by dt60 */
}

